// Generated by `xark client` from `schema.json`: a typed client for the `my_circuit` circuit.
//
//   #[circuit]
//   fn my_circuit(secret: Private<Field>, result: Public<Field>)
//
// `xark build` records the circuit's parameter types in target/xark/my-circuit/schema.json
// and `xark client` turns them into the types below. Don't edit this file: change
// the circuit, then rebuild and rerun `xark client`. Values go in their natural
// forms (dates, strings, variant names, bytes); `@blueshift-gg/xark` encodes them against the
// schema (at the end of the imports), exactly as `xark prove
// --inputs` does.

import { CheckFailed, Circuit, Field, InputError, fromHex, toHex, type FieldInput, type Json, type Proof, type Prover, type Verifier } from "@blueshift-gg/xark/client";
export { CheckFailed, Field, InputError, fromHex, toHex };

// The circuit's schema.json.
const schema = {
  "circuit": "my_circuit",
  "inputs": [
    {
      "name": "secret",
      "type": "field",
      "visibility": "private"
    },
    {
      "name": "result",
      "type": "field",
      "visibility": "public"
    }
  ],
  "public_inputs": [
    "result"
  ],
  "types": {},
  "version": 2,
  "xark": "0.5.0"
};

/** Every input of `my_circuit`. */
export interface MyCircuitInputs {
  secret: FieldInput;
  result: FieldInput;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface MyCircuitPublicInputs {
  result: FieldInput;
}

/** The public inputs, decoded from a proof. */
export interface MyCircuitPublicValues {
  result: Field;
}

/**
 * `my_circuit`: make a prover or verifier from a URL serving a copy of
 * `target/xark/my-circuit/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await MyCircuit.prover("/circuits/my_circuit/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes()); // the proof; an exported Solana verifier reads it as is
 * const verifier = await MyCircuit.verifier(vkBytes);
 * verifier.verify(bytes, publicInputs); // true: it proves the public inputs you require
 * ```
 */
export const MyCircuit = new Circuit<MyCircuitInputs, MyCircuitPublicInputs, MyCircuitPublicValues, {}>({
  name: "my_circuit",
  schema,
  decodePublic,
  client: false,
  digest: "75e3ce529473dfaa2f89a85a0d588228",
});

export type MyCircuitProver = Prover<MyCircuitInputs, MyCircuitPublicInputs, MyCircuitPublicValues, {}>;
export type MyCircuitVerifier = Verifier<MyCircuitPublicInputs, MyCircuitPublicValues, {}>;
export type MyCircuitProof = Proof<MyCircuitPublicValues>;

function decodePublic(v: Json<MyCircuitPublicValues>): MyCircuitPublicValues {
  return {
    result: new Field(v.result),
  };
}
